+
+function streamAll(chunks: string[]): string[][] | "SyntaxError" {
+  try {
+    const s = new CsvStream();
+    const rows: string[][] = [];
+    for (const chunk of chunks) rows.push(...s.push(chunk));
+    rows.push(...s.end());
+    return rows;
+  } catch (e) {
+    if (e instanceof SyntaxError) return "SyntaxError";
+    throw e;
+  }
+}
+
+function parseAll(text: string): string[][] | "SyntaxError" {
+  try {
+    return parseCsv(text);
+  } catch (e) {
+    if (e instanceof SyntaxError) return "SyntaxError";
+    throw e;
+  }
+}
+
+test("streamed rows equal parseCsv for every split", () => {
+  const inputs = [
+    "",
+    "\uFEFF",
+    "\uFEFFa",
+    "\uFEFF\uFEFF",
+    "a\r\nb",
+    "a\rb",
+    "a\r",
+    "\r",
+    "\r\r\n",
+    "a\n",
+    "\n",
+    "a,",
+    '"x""y"',
+    '"a,\r\nb"\r\n',
+    '""',
+    '"a"\r',
+    '"a"\rb',
+    '"a"b',
+    'a"b',
+    '"abc',
+    '"a"""',
+    "a,\r",
+  ];
+  for (const input of inputs) {
+    const expected = parseAll(input);
+    const units = [...input];
+    const splits: string[][] = [[input], units];
+    for (let i = 0; i <= input.length; i++) {
+      splits.push([input.slice(0, i), input.slice(i)]);
+      for (let j = i; j <= input.length; j++) splits.push([input.slice(0, i), input.slice(i, j), input.slice(j)]);
+    }
+    splits.push(["", ...units, ""], units.flatMap((u) => ["", u]));
+    for (const chunks of splits) expect(streamAll(chunks)).toEqual(expected);
+  }
+});
+
+test("a CR and LF in separate chunks make one row end", () => {
+  expect(streamAll(["a\r", "\nb"])).toEqual([["a"], ["b"]]);
+});
+
+test("a doubled quote split across chunks is one quote", () => {
+  expect(streamAll(['"a"', '"b"'])).toEqual([['a"b']]);
+});
+
+test("a BOM alone in a chunk after an empty chunk is dropped", () => {
+  expect(streamAll(["", "\uFEFF", "a"])).toEqual([["a"]]);
+});
+
+test("a CR after a closing quote throws at end, not at push", () => {
+  const s = new CsvStream();
+  expect(s.push('"a"\r')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("an open quoted field throws at end", () => {
+  const s = new CsvStream();
+  expect(s.push('"abc')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("text after a closing quote throws at push", () => {
+  expect(() => new CsvStream().push('"a"b')).toThrow(SyntaxError);
+});
+
+test("a long quoted field and a long row cost a constant amount per unit", () => {
+  const n = 200_000;
+  const s = new CsvStream();
+  let rows: string[][] = [];
+  rows.push(...s.push('"'));
+  for (let i = 0; i < n; i++) rows.push(...s.push("x"));
+  rows.push(...s.push('"'));
+  rows.push(...s.push(","));
+  for (let i = 0; i < n; i++) rows.push(...s.push("y"));
+  rows.push(...s.push("\r\n"));
+  rows.push(...s.end());
+  expect(rows).toEqual([["x".repeat(n), "y".repeat(n)]]);
+}, 4000);
+
+test("a CR at a chunk edge is content unless a LF follows it", () => {
+  expect(streamAll([",\r", ","])).toEqual([["", "\r", ""]]);
+  expect(streamAll(['a\r"'])).toBe("SyntaxError");
+  expect(streamAll(['"a"\r,'])).toBe("SyntaxError");
+  expect(streamAll(['"a"\r'])).toBe("SyntaxError");
+  expect(streamAll(['""'])).toEqual([[""]]);
+});
+
+test("random inputs over the special characters match parseCsv for random chunkings", () => {
+  const alphabet = ['a', ",", '"', "\r", "\n", "\uFEFF"];
+  let seed = 12345;
+  const rand = (n: number) => {
+    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
+    return seed % n;
+  };
+  for (let t = 0; t < 3000; t++) {
+    let input = "";
+    const len = rand(9);
+    for (let i = 0; i < len; i++) input += alphabet[rand(alphabet.length)];
+    const chunks: string[] = [];
+    let at = 0;
+    while (at < input.length) {
+      const size = rand(4);
+      chunks.push(input.slice(at, at + size));
+      at += size;
+    }
+    expect(streamAll(chunks)).toEqual(parseAll(input));
+  }
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-24 02:26:50.925354672 +0000
+++ b/csv.ts	2026-10-24 02:27:59.904860638 +0000
@@ -50,3 +50,97 @@
   rows.push(row);
   return rows;
 }
+
+type StreamState = "start" | "unquoted" | "quoted" | "quote" | "after";
+
+/**
+ * parseCsv for input that arrives in chunks. Rows come back from push() as soon as their row end has arrived, and
+ * the rest from end(). The work per unit is constant, so a chunk costs the same however much came before it.
+ */
+export class CsvStream {
+  private rows: string[][] = [];
+  private row: string[] = [];
+  private field = "";
+  private state: StreamState = "start";
+  private cr = false;
+  private offset = 0;
+
+  push(chunk: string): string[][] {
+    this.rows = [];
+    for (let k = 0; k < chunk.length; k++) {
+      const c = chunk[k]!;
+      if (this.offset++ === 0 && c === "\uFEFF") continue;
+      this.unit(c);
+    }
+    return this.rows;
+  }
+
+  end(): string[][] {
+    this.rows = [];
+    if (this.cr) {
+      if (this.state === "after") throw new SyntaxError('unexpected "\\r" after a closing quote');
+      this.field += "\r";
+      this.state = "unquoted";
+      this.cr = false;
+    }
+    if (this.state === "quoted") throw new SyntaxError("a quoted field is still open at the end of the input");
+    if (this.state === "start" && this.row.length === 0) return this.rows;
+    this.row.push(this.field);
+    this.rows.push(this.row);
+    return this.rows;
+  }
+
+  private unit(c: string) {
+    if (this.cr) {
+      this.cr = false;
+      if (c === "\n") return this.endRow();
+      if (this.state === "after") throw new SyntaxError('unexpected "\\r" after a closing quote');
+      this.field += "\r";
+      this.state = "unquoted";
+    }
+    if (this.state === "start") {
+      if (c === '"') this.state = "quoted";
+      else if (c === ",") this.endField();
+      else if (c === "\n") this.endRow();
+      else if (c === "\r") this.cr = true;
+      else {
+        this.field = c;
+        this.state = "unquoted";
+      }
+    } else if (this.state === "unquoted") {
+      if (c === ",") this.endField();
+      else if (c === "\n") this.endRow();
+      else if (c === "\r") this.cr = true;
+      else if (c === '"') throw new SyntaxError("a quote in a field that is not quoted");
+      else this.field += c;
+    } else if (this.state === "quoted") {
+      if (c === '"') this.state = "quote";
+      else this.field += c;
+    } else if (this.state === "quote") {
+      if (c === '"') {
+        this.field += '"';
+        this.state = "quoted";
+        return;
+      }
+      this.state = "after";
+    }
+    if (this.state === "after") {
+      if (c === ",") this.endField();
+      else if (c === "\n") this.endRow();
+      else if (c === "\r") this.cr = true;
+      else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+    }
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = "start";
+  }
+
+  private endRow() {
+    this.endField();
+    this.rows.push(this.row);
+    this.row = [];
+  }
+}

