@@ -0,0 +1,35 @@
+import { expect, test } from 'bun:test';
+import { denyListed } from './deny.ts';
+
+const cwd = '/work/repo';
+const hit = (line: string) => denyListed(line.split(' '), cwd)?.name;
+
+test('find leading options and -ok/-okdir', () => {
+  expect(denyListed(['find', '-L', '/', '-delete'], cwd)?.name).toBe('rm-outside');
+  expect(denyListed(['find', '-P', '..', '-exec', 'rm', '{}', ';'], cwd)?.name).toBe('rm-outside');
+  expect(hit('find / -ok rm {} ;')).toBe('rm-outside');
+  expect(hit('find -L -delete')).toBeUndefined();
+  expect(hit('find /work/repo -delete')).toBeUndefined();
+});
+
+test('abbreviated long options', () => {
+  expect(denyListed(['rm', '--recur', '/etc'], cwd)?.name).toBe('rm-outside');
+  expect(denyListed(['git', 'reset', '--har'], cwd)?.name).toBe('reset-hard');
+  expect(denyListed(['git', 'clean', '--forc'], cwd)?.name).toBe('clean-force');
+  expect(denyListed(['git', 'push', '--forc'], cwd)?.name).toBe('force-push');
+});
+
+test('git global options, long option values, clean dry run', () => {
+  expect(hit('git --work-tree x push -f')).toBe('force-push');
+  expect(hit('git --namespace x push -f')).toBe('force-push');
+  expect(hit('git push --delete=old')).toBe('force-push');
+  expect(hit('git push --mirror=x')).toBe('force-push');
+  expect(hit('git clean --force --dry-run')).toBeUndefined();
+  expect(hit('git')).toBeUndefined();
+  expect(hit('git -C dir')).toBeUndefined();
+});
+
+test('rm edge targets and find on ~user', () => {
+  expect(hit('rm -rf --')).toBe('rm-outside');
+  expect(hit('find ~bob -delete')).toBe('rm-outside');
+});
