+    if (!argv.some((w) => ['-delete', '-exec', '-execdir', '-ok', '-okdir'].includes(w))) return undefined;
+    // Leading global options (-H, -L, -P, -Olevel, -D debugopts) come before the start paths.
+    let i = 1;
+    while (i < argv.length && (/^-[HLP]$/.test(argv[i]) || /^-O\d+$/.test(argv[i]) || argv[i] === '-D')) {
