diff -ruN '--exclude=node_modules' '--exclude=.git' a/edit.cases.test.ts b/edit.cases.test.ts
--- a/edit.cases.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/edit.cases.test.ts	2026-10-24 02:28:59.100859284 +0000
@@ -0,0 +1,49 @@
+import { describe, expect, test } from 'bun:test';
+import { applyEdit } from './edit.ts';
+
+const SRC = 'function f() {\n    if (a) {\n        return 1;  \n    }\n}\n';
+const ok = (r: ReturnType<typeof applyEdit>) => {
+  if ('error' in r) throw new Error(r.error);
+  return r;
+};
+
+describe('overlapping matches', () => {
+  test('overlapping exact matches are counted', () => {
+    const r = applyEdit('}\n}\n}\n', { old_text: '}\n}\n', new_text: 'X\n' });
+    expect('error' in r && r.error).toContain('matches 2 places');
+  });
+});
+
+describe('CRLF files', () => {
+  test('replacement lines keep CRLF endings', () => {
+    const r = ok(applyEdit('a\r\nb\r\nc\r\n', { old_text: 'a \nb', new_text: 'x\ny' }));
+    expect(r.content).toBe('x\r\ny\r\nc\r\n');
+  });
+});
+
+describe('indentation fallback', () => {
+  test('new_text line less indented than old_text first line gets file indent', () => {
+    const r = ok(applyEdit(SRC, { old_text: '  if (a) {\n      return 1;\n  }', new_text: ' if (b) {\n      return 1;\n  }' }));
+    expect(r.applied).toEqual({ from: 2, to: 4, tier: 'indentation', count: 1 });
+    expect(r.content).toBe('function f() {\n    if (b) {\n        return 1;\n    }\n}\n');
+  });
+});
+
+describe('not-found line cap', () => {
+  test('at most 5 line numbers are listed', () => {
+    const r = applyEdit('x foo bar\n'.repeat(7), { old_text: 'foo bar\nzzz', new_text: 'x' });
+    expect('error' in r && r.error).toContain('first line appears at line 1, 2, 3, 4, 5');
+    expect('error' in r && r.error).not.toContain('6');
+  });
+});
+
+describe('replace_all without an exact match', () => {
+  test('falls through to the line tiers and applies a single match', () => {
+    const r = ok(applyEdit(SRC, { old_text: '    if (a) {\n        return 1;\n    }', new_text: '    if (a) {\n        return 3;\n    }', replace_all: true }));
+    expect(r.applied).toEqual({ from: 2, to: 4, tier: 'trailing-space', count: 1 });
+  });
+  test('line tiers still reject several matches', () => {
+    const r = applyEdit('x \ny\nx \ny\n', { old_text: 'x\ny', new_text: 'z', replace_all: true });
+    expect('error' in r && r.error).toContain('matches 2 places');
+  });
+});
