+  const re = /(\d+(?:\.\d+)?)(ms|d|h|m|s)\s*/y;
+  let total = 0;
+  let pos = 0;
+  while (pos < s.length) {
+    re.lastIndex = pos;
+    const match = re.exec(s);
+    if (!match || match.index !== pos) throw new Error(`invalid duration "${text}"`);
+    total += Number(match[1]) * units[match[2]];
+    pos = re.lastIndex;
+  }
