+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+
+test('parseDuration rejects invalid input', () => {
+  for (const bad of ['', '   ', '10', '5x', 'h', '-1s', '1 h', '1.h', 's5']) {
+    expect(() => parseDuration(bad)).toThrow(`"${bad}"`);
+  }
+});
+
+test('parseDuration parses valid input', () => {
+  expect(parseDuration('90s')).toBe(90_000);
+  expect(parseDuration('1h30m')).toBe(5_400_000);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('2d 4h')).toBe(187_200_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('  1m  ')).toBe(60_000);
+  expect(parseDuration('1m 30s')).toBe(90_000);
+  expect(parseDuration('1.0005s')).toBe(1001);
+});
+
+test('formatDuration', () => {
+  expect(formatDuration(5_400_000)).toBe('1h30m');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(250)).toBe('250ms');
+  expect(formatDuration(86_400_000)).toBe('1d');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+  expect(() => formatDuration(-1)).toThrow('invalid duration -1');
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/lru.extra.test.ts b/test/lru.extra.test.ts
--- a/test/lru.extra.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/lru.extra.test.ts	2026-10-24 02:34:57.332938398 +0000
@@ -0,0 +1,103 @@
+import { expect, test } from 'bun:test';
+import { LRU } from '../src/lru.ts';
+
+function setup(capacity: number, ttl: number) {
+  let t = 0;
+  const cache = new LRU<string, number>(capacity, ttl, () => t);
+  const events: [string, number, string][] = [];
+  cache.onEvict = (k, v, r) => events.push([k, v, r]);
+  return { cache, events, setNow: (n: number) => (t = n) };
+}
+
+test('capacity evicts the least recently used entry', () => {
+  const { cache, events } = setup(2, 1000);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.set('c', 3);
+  expect(events).toEqual([['a', 1, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('get makes an entry most recently used', () => {
+  const { cache, events } = setup(2, 1000);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.get('a');
+  cache.set('c', 3);
+  expect(events).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
+test('ttl boundary: live at 999, expired at 1000', () => {
+  const { cache, events, setNow } = setup(2, 1000);
+  cache.set('a', 1);
+  setNow(999);
+  expect(cache.get('a')).toBe(1);
+  setNow(1000);
+  expect(cache.get('a')).toBeUndefined();
+  expect(events).toEqual([['a', 1, 'expired']]);
+});
+
+test('expired entries are removed before capacity eviction', () => {
+  const { cache, events, setNow } = setup(2, 1000);
+  cache.set('a', 1);
+  setNow(500);
+  cache.set('b', 2);
+  setNow(1200);
+  cache.set('c', 3);
+  expect(events).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('expired entries still count toward capacity', () => {
+  const { cache, events, setNow } = setup(2, 1000);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  setNow(2000);
+  cache.set('c', 3);
+  expect(events).toEqual([
+    ['a', 1, 'expired'],
+    ['b', 2, 'expired'],
+  ]);
+  expect(cache.size).toBe(1);
+});
+
+test('delete reports live and expired entries', () => {
+  const { cache, events, setNow } = setup(5, 1000);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.delete('a')).toBe(true);
+  expect(events).toEqual([['a', 1, 'delete']]);
+  setNow(1000);
+  expect(cache.delete('b')).toBe(false);
+  expect(events).toEqual([
+    ['a', 1, 'delete'],
+    ['b', 2, 'expired'],
+  ]);
+  events.length = 0;
+  expect(cache.delete('missing')).toBe(false);
+  expect(events).toEqual([]);
+});
+
+test('size and keys skip expired entries without events', () => {
+  const { cache, events, setNow } = setup(5, 1000);
+  cache.set('a', 1);
+  setNow(500);
+  cache.set('b', 2);
+  setNow(1000);
+  expect(cache.size).toBe(1);
+  expect(cache.keys()).toEqual(['b']);
+  expect(events).toEqual([]);
+});
+
+test('setting an existing key replaces, refreshes ttl, and fires no event', () => {
+  const { cache, events, setNow } = setup(2, 1000);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  setNow(900);
+  cache.set('a', 10);
+  expect(events).toEqual([]);
+  expect(cache.keys()).toEqual(['a', 'b']);
+  setNow(1500);
+  expect(cache.get('a')).toBe(10);
+});
